#[derive(Debug)]
enum Rule {
    RequireHeader { name: String },
    MaxHeaderSize { limit: usize },
    HeaderPrefix { name: String, prefix: String },
    MaxTotalHeaders { max: usize },
}

#[derive(Debug, Default)]
struct Validator {
    rules: Vec<Rule>,
}

impl MetadataValidator for Validator {
    fn validate(&self, metadata: &MetadataMap) -> Result<(), Status> {
        for rule in self.rules.iter() {
            match rule {
                Rule::RequireHeader { name } => {
                    if !metadata.contains_key(name.as_str()) {
                        return Err(Status::failed_precondition("required metadata missing"));
                    }
                }
                Rule::MaxHeaderSize { limit } => {
                    let headers = metadata.as_ref();
                    for (name, value) in headers.iter() {
                        let mut size = name.as_str().len();
                        size += value.as_bytes().len();
                        if size > *limit {
                            return Err(Status::invalid_argument("metadata header too large"));
                        }
                    }
                }
                Rule::HeaderPrefix { name, prefix } => {
                    match metadata.get(name.as_str()) {
                        Some(value) => match value.to_str() {
                            Ok(s) => {
                                if !s.starts_with(prefix.as_str()) {
                                    return Err(Status::invalid_argument(
                                        "metadata header does not match prefix",
                                    ));
                                }
                            }
                            Err(_) => {
                                return Err(Status::invalid_argument("metadata header not ascii"));
                            }
                        },
                        None => {
                            return Err(Status::invalid_argument("metadata header missing"));
                        }
                    }
                }
                Rule::MaxTotalHeaders { max } => {
                    if metadata.len() > *max {
                        return Err(Status::resource_exhausted("too many metadata headers"));
                    }
                }
            }
        }

        Ok(())
    }
}

