    pub fn new() -> Self {
        Self { rules: Vec::new() }
    }

    /// Require the presence of a metadata header.
    pub fn require_header(mut self, name: impl Into<String>) -> Self {
        self.rules.push(Rule::RequireHeader { name: name.into() });
        self
    }

    /// Enforce a maximum per-header size (name + value) in bytes.
    pub fn max_header_size(mut self, limit: usize) -> Self {
